  const candidates = await prisma.candidateProfile.findMany({
    where: {
      anonymizedAt: null,
      applications: {
        some: { job: { orgId } },
        every: { status: { in: ["REJECTED", "WITHDRAWN"] }, updatedAt: { lt: cutoff } }
      }
    },
    select: { userId: true }
  });
  for (const c of candidates) await anonymizeCandidate(c.userId);
